            for sign in ['-1','1']:
                f=ms[name]['first_failure'][threshold][sign];z=f['first_measured_failure'];desc.append(('negative' if sign=='-1' else 'positive')+(': no measured failure' if z is None else f": {z['id']} at ({z['point'][0]:.2f}, {z['point'][1]:.2f}), arc {z['arc']:.2f}px, conditional {z['index']}, {z['visible']:.1%}; {f['preceding_measured_passes']} earlier measured passes"))
